insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('qui-t01','quimica','Química orgânica (introdução)','treino','A Química Orgânica é o ramo da química que estuda:','["As substâncias que não têm carbono", "Os compostos do carbono", "Somente as substâncias produzidas por seres vivos", "Os metais e suas ligas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t02','quimica','Química orgânica (introdução)','treino','O que dizia a antiga teoria da "força vital"?','["Que todo composto tem carbono", "Que o carbono faz quatro ligações", "Que compostos orgânicos só podiam ser produzidos por seres vivos", "Que os aromas vêm de moléculas voláteis"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t03','quimica','Química orgânica (introdução)','treino','Em 1828, Friedrich Wöhler aqueceu cianato de amônio, uma substância inorgânica, e obteve:','["Glicose", "Etanol", "Ureia", "Benzeno"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t04','quimica','Química orgânica (introdução)','treino','Por que o experimento de Wöhler abalou a teoria da força vital?','["Porque provou que a ureia não tem carbono", "Porque descobriu um novo elemento químico", "Porque produziu em laboratório um composto orgânico, sem nenhum ser vivo", "Porque transformou um metal em ouro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t05','quimica','Química orgânica (introdução)','treino','Quem propôs, em 1859, a definição atual de Química Orgânica como a química dos compostos do carbono?','["Wöhler", "Mendeleev", "Kekulé", "Lavoisier"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t06','quimica','Química orgânica (introdução)','treino','Qual destas substâncias é ORGÂNICA?','["Água (H₂O)", "Etanol (CH₃CH₂OH)", "Ácido sulfúrico (H₂SO₄)", "Cloreto de sódio (NaCl)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t07','quimica','Química orgânica (introdução)','treino','Qual destas substâncias tem carbono, mas é classificada como INORGÂNICA?','["Metano (CH₄)", "Carbonato de cálcio (CaCO₃)", "Acetona (CH₃COCH₃)", "Benzeno (C₆H₆)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t08','quimica','Química orgânica (introdução)','treino','Além do carbono, quais elementos aparecem com mais frequência nos compostos orgânicos?','["Hélio, neônio e argônio", "Sódio, potássio e cálcio", "Hidrogênio, oxigênio e nitrogênio", "Ferro, cobre e zinco"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t09','quimica','Química orgânica (introdução)','treino','Hidrocarboneto é um composto formado:','["Por carbono, hidrogênio e oxigênio, obrigatoriamente", "Somente por átomos de carbono", "Somente por carbono e oxigênio", "Somente por carbono e hidrogênio"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t10','quimica','Química orgânica (introdução)','treino','Que tipo de ligação une o carbono aos hidrogênios no metano (CH₄)?','["Iônica", "Covalente", "Ponte de hidrogênio", "Metálica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t11','quimica','Química orgânica (introdução)','treino','Por que existe um número tão grande de compostos de carbono?','["Porque o carbono é um metal muito reativo", "Porque o carbono muda de valência o tempo todo", "Porque o carbono forma ligações iônicas com facilidade", "Porque o carbono faz quatro ligações e se liga a outros carbonos formando cadeias"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t12','quimica','Química orgânica (introdução)','treino','Para sentirmos o cheiro de uma substância, as moléculas dela precisam:','["Evaporar com facilidade e chegar ao nariz (ser voláteis)", "Dissolver-se na água do copo", "Ser muito pesadas", "Ser metálicas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t13','quimica','Química orgânica (introdução)','treino','Os ésteres, comuns em frutas, costumam ter aroma:','["De queimado", "Frutado", "Nenhum: ésteres não têm cheiro", "De ovo podre"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t14','quimica','Química orgânica (introdução)','treino','No dia a dia, chamamos de "lixo orgânico" os restos de origem animal ou vegetal. Qual destes vai para esse lixo?','["Prego enferrujado", "Lata de alumínio", "Cascas de frutas e borra de café", "Garrafa de vidro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t15','quimica','Química orgânica (introdução)','treino','Qual grupo reúne apenas produtos ligados à Química Orgânica?','["Sal de cozinha, água e areia", "Plásticos, medicamentos e biocombustíveis", "Vidro, cal e cimento", "Ferro, ouro e prata"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t16','quimica','Classificação geral do carbono','treino','O 1º postulado de Kekulé diz que, nos compostos orgânicos, o carbono:','["É bivalente: faz duas ligações", "É tetravalente: faz quatro ligações", "É pentavalente: faz cinco ligações", "É trivalente: faz três ligações"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t17','quimica','Classificação geral do carbono','treino','Só existe UM composto com fórmula CH₃Cl, não importa em qual das quatro posições o cloro esteja. Isso mostra que:','["O carbono forma cadeias fechadas", "As quatro ligações do carbono são equivalentes", "O carbono só faz uma ligação", "O cloro não se liga ao carbono"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t18','quimica','Classificação geral do carbono','treino','O 3º postulado de Kekulé (encadeamento) afirma que:','["Átomos de carbono podem se ligar uns aos outros, formando cadeias", "O carbono só se liga ao hidrogênio", "Cada molécula só pode ter um carbono", "O carbono não forma anéis"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t19','quimica','Classificação geral do carbono','treino','Numa ligação dupla entre dois carbonos, eles compartilham:','["Três pares de elétrons", "Dois pares de elétrons", "Quatro pares de elétrons", "Um par de elétrons"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t20','quimica','Classificação geral do carbono','treino','No etino (H–C≡C–H), a ligação entre os dois carbonos é:','["Simples", "Dupla", "Iônica", "Tripla"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t21','quimica','Classificação geral do carbono','treino','Uma cadeia tem 3 carbonos: C=C–C (dupla entre o 1º e o 2º). Completando com hidrogênios, quantos H a molécula terá?','["7", "8", "4", "6"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t22','quimica','Classificação geral do carbono','treino','Qual combinação de ligações é IMPOSSÍVEL para um átomo de carbono?','["Duas ligações triplas", "Quatro ligações simples", "Uma dupla e duas simples", "Uma tripla e uma simples"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t23','quimica','Classificação geral do carbono','treino','Na cadeia C–C≡C–C, quantos hidrogênios o 2º carbono (o primeiro da tripla) terá?','["1", "0", "3", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t24','quimica','Classificação geral do carbono','treino','Carbono primário é aquele ligado a:','["Três outros átomos de carbono", "Dois outros átomos de carbono", "Apenas um outro átomo de carbono", "Quatro outros átomos de carbono"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t25','quimica','Classificação geral do carbono','treino','Um carbono ligado a três outros átomos de carbono é classificado como:','["Terciário", "Primário", "Secundário", "Quaternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t26','quimica','Classificação geral do carbono','treino','No propano, CH₃–CH₂–CH₃, o carbono do meio é:','["Primário", "Quaternário", "Secundário", "Terciário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t27','quimica','Classificação geral do carbono','treino','Por convenção, um carbono isolado, que não está ligado a nenhum outro carbono (como o do metano, CH₄), é classificado como:','["Secundário", "Terciário", "Primário", "Quaternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t28','quimica','Classificação geral do carbono','treino','Na molécula CH₃–CH(CH₃)–CH₃, quantos carbonos primários existem? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["1", "3", "4", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t29','quimica','Classificação geral do carbono','treino','Na molécula CH₃–C(CH₃)₂–CH₂–CH₃, como se classifica o carbono que carrega os dois CH₃ entre parênteses? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["Secundário", "Quaternário", "Terciário", "Primário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t30','quimica','Classificação geral do carbono','treino','Na molécula CH₃–CH(CH₃)–CH₂–CH₂–CH₃, quantos carbonos são primários, secundários e terciários, nessa ordem? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["3, 3 e 0", "2, 3 e 1", "3, 2 e 1", "4, 1 e 1"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t31','quimica','Classificação geral do carbono','treino','Qual é a fórmula molecular do butano, CH₃–CH₂–CH₂–CH₃?','["C₄H₈", "C₃H₁₀", "C₄H₁₂", "C₄H₁₀"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t32','quimica','Classificação geral do carbono','treino','Na fórmula em bastão (zigue-zague), cada ponta e cada vértice representa:','["Um átomo de hidrogênio", "Uma ligação dupla", "Um átomo de carbono", "Um átomo de oxigênio"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t33','quimica','Classificação geral do carbono','treino','Na fórmula em bastão, os hidrogênios ligados aos carbonos:','["Não aparecem; são deduzidos sabendo que o carbono faz 4 ligações", "Aparecem como pequenas bolinhas", "Não existem nessas moléculas", "Aparecem como traços duplos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t34','quimica','Classificação geral do carbono','treino','Uma fórmula em bastão é um zigue-zague simples com 5 pontos (2 pontas e 3 vértices), sem nenhuma letra. Qual é a fórmula molecular?','["C₃H₈", "C₅H₁₄", "C₅H₁₀", "C₅H₁₂"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t35','quimica','Classificação geral do carbono','treino','Qual é a fórmula molecular de CH₃–CH=CH–CH₃?','["C₄H₆", "C₄H₈", "C₄H₁₀", "C₂H₄"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t36','quimica','Classificação geral de cadeia','treino','Uma cadeia aberta (acíclica) é aquela que:','["Forma um anel de seis carbonos", "Tem pelo menos uma ligação dupla", "Tem um átomo de oxigênio entre carbonos", "Não forma nenhum anel fechado"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t37','quimica','Classificação geral de cadeia','treino','O ciclobutano tem quatro carbonos ligados formando um quadrado. Sua cadeia é:','["Fechada (cíclica)", "Heterogênea", "Aromática", "Aberta (acíclica)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t38','quimica','Classificação geral de cadeia','treino','Uma cadeia RAMIFICADA:','["Tem pelo menos um carbono terciário ou quaternário e mais de duas pontas", "Tem um heteroátomo entre carbonos", "Tem só duas pontas", "Tem apenas ligações duplas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t39','quimica','Classificação geral de cadeia','treino','Uma cadeia SATURADA é aquela em que os carbonos estão ligados entre si:','["Somente por ligações simples", "Através de átomos de oxigênio", "Por pelo menos uma ligação dupla", "Por pelo menos uma ligação tripla"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t40','quimica','Classificação geral de cadeia','treino','Como se classifica a cadeia de CH₂=CH–CH₂–CH₃?','["Aberta, normal, saturada e heterogênea", "Fechada, normal, insaturada e heterogênea", "Aberta, ramificada, saturada e homogênea", "Aberta, normal, insaturada e homogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t41','quimica','Classificação geral de cadeia','treino','Heteroátomo é:','["Um carbono ligado a quatro carbonos", "Um átomo de carbono com ligação dupla", "Qualquer átomo de hidrogênio da molécula", "Um átomo diferente de C e H que fica entre dois carbonos da cadeia"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t42','quimica','Classificação geral de cadeia','treino','A cadeia do éter dimetílico, CH₃–O–CH₃, é heterogênea porque:','["Ela forma um anel", "O oxigênio está entre dois carbonos", "Ela tem uma ligação dupla", "Ela tem um carbono quaternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t43','quimica','Classificação geral de cadeia','treino','Por que a cadeia do etanol, CH₃–CH₂–OH, é HOMOGÊNEA, mesmo tendo oxigênio?','["Porque o oxigênio está na ponta, e não entre dois carbonos", "Porque o etanol não tem carbono", "Porque o etanol tem ligação dupla", "Porque o oxigênio não conta como átomo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t44','quimica','Classificação geral de cadeia','treino','Como se classifica a cadeia de CH₃–CH(CH₃)–CH₂–CH₃? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["Aberta, ramificada, saturada e homogênea", "Fechada, ramificada, saturada e homogênea", "Aberta, normal, saturada e homogênea", "Aberta, ramificada, insaturada e heterogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t45','quimica','Classificação geral de cadeia','treino','Como se classifica a cadeia de CH₃–CH₂–NH–CH₃?','["Aberta, normal, saturada e heterogênea", "Fechada, normal, insaturada e heterogênea", "Aberta, ramificada, saturada e homogênea", "Aberta, normal, insaturada e homogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t46','quimica','Classificação geral de cadeia','treino','Como se classifica a cadeia de CH₃–CH=CH–CH(CH₃)–CH₃? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["Aberta, ramificada, insaturada e homogênea", "Aberta, normal, insaturada e homogênea", "Aberta, ramificada, saturada e homogênea", "Fechada, ramificada, insaturada e heterogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t47','quimica','Classificação geral de cadeia','treino','Uma cadeia é chamada de AROMÁTICA quando:','["É aberta e ramificada", "Tem um heteroátomo", "Tem cheiro forte", "Tem pelo menos um anel benzênico"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t48','quimica','Classificação geral de cadeia','treino','No benzeno (C₆H₆), as ligações duplas podem ser desenhadas em duas posições, que são igualmente válidas; por isso o anel costuma ser desenhado com um círculo dentro. Esse fenômeno se chama:','["Saturação", "Ressonância", "Ramificação", "Força vital"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t49','quimica','Classificação geral de cadeia','treino','O naftaleno (a naftalina) tem dois anéis benzênicos que compartilham um lado. Sua cadeia é:','["Aromática polinuclear condensada", "Aromática mononuclear", "Alicíclica saturada", "Aberta e ramificada"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-t50','quimica','Classificação geral de cadeia','treino','Uma cadeia fechada SEM anel benzênico, como a do ciclo-hexano (C₆H₁₂), é chamada:','["Acíclica", "Aromática", "Heterogênea", "Alicíclica (não aromática)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p01','quimica','Química orgânica (introdução)','prova','Qual destas substâncias é ORGÂNICA?','["Cianeto de sódio (NaCN)", "Monóxido de carbono (CO)", "Ácido carbônico (H₂CO₃)", "Acetona (CH₃COCH₃)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p02','quimica','Química orgânica (introdução)','prova','O que a síntese da ureia por Wöhler, em 1828, mostrou?','["Que um composto orgânico pode ser produzido em laboratório a partir de um inorgânico", "Que a ureia não contém carbono", "Que só seres vivos produzem compostos orgânicos", "Que o carbono faz cinco ligações"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p03','quimica','Química orgânica (introdução)','prova','Qual característica do carbono explica a enorme quantidade de compostos orgânicos?','["Ter valência variável", "Fazer ligações iônicas com facilidade", "Fazer quatro ligações covalentes e se ligar a outros carbonos em cadeias", "Ser um metal muito reativo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p04','quimica','Química orgânica (introdução)','prova','Os tióis, compostos orgânicos com enxofre, estão ligados a cheiros:','["Nenhum: são inodoros", "De frutas maduras", "Desagradáveis, como o de ovo podre", "De flores"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p05','quimica','Classificação geral do carbono','prova','Na molécula CH₃–C(CH₃)₂–CH(CH₃)–CH₃, quantos carbonos são primários, terciários e quaternários, nessa ordem? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["5, 2 e 0", "3, 1 e 2", "5, 1 e 1", "4, 1 e 1"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p06','quimica','Classificação geral do carbono','prova','Qual é a fórmula molecular de CH₂=CH–C≡CH?','["C₄H₈", "C₄H₄", "C₄H₁₀", "C₄H₆"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p07','quimica','Classificação geral do carbono','prova','Na fórmula CH₃–CH₂–C≡N, quantas ligações o carbono ligado ao nitrogênio faz com o N?','["3", "1", "4", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p08','quimica','Classificação geral do carbono','prova','Uma fórmula em bastão é um zigue-zague simples com 6 pontos (2 pontas e 4 vértices), sem nenhuma letra. Qual é a fórmula molecular?','["C₆H₁₄", "C₆H₆", "C₄H₁₀", "C₆H₁₂"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p09','quimica','Classificação geral de cadeia','prova','Como se classifica a cadeia de CH₃–CH₂–O–CH₂–CH₃?','["Fechada, normal, saturada e heterogênea", "Aberta, ramificada, saturada e homogênea", "Aberta, normal, insaturada e homogênea", "Aberta, normal, saturada e heterogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p10','quimica','Classificação geral de cadeia','prova','Como se classifica a cadeia de CH₃–C(CH₃)=CH–CH₃? (O grupo entre parênteses está preso ao carbono escrito logo antes dele.)','["Fechada, ramificada, insaturada e homogênea", "Aberta, normal, insaturada e homogênea", "Aberta, ramificada, saturada e heterogênea", "Aberta, ramificada, insaturada e homogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p11','quimica','Classificação geral de cadeia','prova','Como se classifica a cadeia do ciclo-hexano (C₆H₁₂), um anel de seis carbonos só com ligações simples?','["Fechada, aromática, insaturada e homogênea", "Fechada, alicíclica, saturada e heterogênea", "Fechada, alicíclica, saturada e homogênea", "Aberta, normal, saturada e homogênea"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('qui-p12','quimica','Classificação geral de cadeia','prova','Qual destes compostos tem cadeia AROMÁTICA?','["Ciclo-hexano (C₆H₁₂)", "Hexano (C₆H₁₄)", "Ciclopropano (C₃H₆)", "Benzeno (C₆H₆)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('qui-t01',1,'Definição atual: Química Orgânica é a química dos compostos do carbono, sejam eles naturais ou feitos em laboratório.'),
  ('qui-t02',2,'Acreditava-se que só plantas e animais, com uma "força vital", conseguiam fabricar compostos orgânicos.'),
  ('qui-t03',2,'Wöhler produziu ureia (substância orgânica, presente na urina) a partir de um composto inorgânico.'),
  ('qui-t04',2,'Se um composto orgânico pode ser feito no laboratório, não é preciso "força vital" para produzi-lo.'),
  ('qui-t05',2,'August Kekulé (1859). Antes, em 1848, Gmelin já tinha notado que todos os compostos orgânicos têm carbono.'),
  ('qui-t06',1,'O etanol tem cadeia de carbono ligada a hidrogênios. As outras não têm carbono.'),
  ('qui-t07',1,'Algumas substâncias com carbono são inorgânicas: CO₂, CO, carbonatos, ácido carbônico, cianetos, grafite e diamante.'),
  ('qui-t08',2,'Os orgânicos têm carbono quase sempre com hidrogênio, e muitas vezes oxigênio, nitrogênio, enxofre e halogênios.'),
  ('qui-t09',3,'Hidro (hidrogênio) + carboneto (carbono): só C e H, como o metano (CH₄) e o butano (C₄H₁₀).'),
  ('qui-t10',1,'Nos compostos orgânicos, os átomos compartilham pares de elétrons: ligação covalente.'),
  ('qui-t11',3,'Tetravalência + encadeamento: os carbonos formam cadeias abertas ou fechadas, de vários tamanhos e com ramificações.'),
  ('qui-t12',0,'Aromas são moléculas voláteis: evaporam, espalham-se no ar e chegam aos receptores do olfato.'),
  ('qui-t13',1,'Ésteres dão o cheiro de frutas; os tióis é que lembram ovo podre.'),
  ('qui-t14',2,'Restos de comida e cascas são de origem vegetal. Metal e vidro são lixo reciclável inorgânico.'),
  ('qui-t15',1,'Plásticos, remédios, fibras sintéticas e biocombustíveis são feitos de compostos de carbono.'),
  ('qui-t16',1,'Tetravalência: o carbono sempre completa quatro ligações covalentes.'),
  ('qui-t17',1,'É o 2º postulado: as quatro valências do carbono são iguais entre si.'),
  ('qui-t18',0,'Os carbonos se ligam entre si em cadeias abertas ou fechadas, por isso existem milhões de compostos orgânicos.'),
  ('qui-t19',1,'Simples = 1 par, dupla = 2 pares, tripla = 3 pares de elétrons compartilhados.'),
  ('qui-t20',3,'O sinal ≡ (três traços) indica ligação tripla. Cada carbono ainda faz uma simples com H: 3 + 1 = 4.'),
  ('qui-t21',3,'1º carbono: 2 ligações com C (dupla) → 2 H. 2º: 3 ligações com C → 1 H. 3º: 1 ligação → 3 H. Total 2 + 1 + 3 = 6 (propeno, C₃H₆).'),
  ('qui-t22',0,'Duas triplas dariam 6 ligações. O carbono faz exatamente 4: 1+1+1+1, 2+1+1, 3+1 ou 2+2.'),
  ('qui-t23',1,'Ele já tem 1 ligação com o 1º carbono e 3 com o 3º: 4 ligações. Não sobra lugar para H.'),
  ('qui-t24',2,'Primário: 1 carbono vizinho; secundário: 2; terciário: 3; quaternário: 4.'),
  ('qui-t25',0,'Conta-se só quantos carbonos estão ligados a ele: três → terciário.'),
  ('qui-t26',2,'O CH₂ do meio está ligado aos dois CH₃: dois carbonos vizinhos → secundário.'),
  ('qui-t27',2,'Por extensão, o carbono isolado é considerado primário.'),
  ('qui-t28',1,'Os três CH₃ (dois nas pontas e o do parêntese) estão ligados só ao carbono do meio: 3 primários. O do meio é terciário.'),
  ('qui-t29',1,'Ele está ligado ao CH₃ da esquerda, aos dois CH₃ do parêntese e ao CH₂: quatro carbonos → quaternário.'),
  ('qui-t30',2,'Primários: os dois CH₃ das pontas e o CH₃ do parêntese (3). Secundários: os dois CH₂ (2). Terciário: o CH com o ramo (1).'),
  ('qui-t31',3,'Carbonos: 4. Hidrogênios: 3 + 2 + 2 + 3 = 10. Fórmula C₄H₁₀.'),
  ('qui-t32',2,'No bastão, cada vértice e cada ponta é um carbono; cada traço é uma ligação.'),
  ('qui-t33',0,'O leitor completa os H. Só os outros elementos (O, N…) e os H ligados a eles são escritos.'),
  ('qui-t34',3,'São 5 carbonos em cadeia com ligações simples: CH₃–CH₂–CH₂–CH₂–CH₃ (pentano), com 3+2+2+2+3 = 12 H.'),
  ('qui-t35',1,'4 carbonos; hidrogênios: 3 + 1 + 1 + 3 = 8. Fórmula C₄H₈.'),
  ('qui-t36',3,'Aberta = as pontas não se juntam. Fechada (cíclica) = os carbonos formam um anel.'),
  ('qui-t37',0,'Os carbonos formam um anel: cadeia fechada. Como não há anel benzênico, ela não é aromática.'),
  ('qui-t38',0,'Ramificada tem "galhos": mais de duas extremidades. Normal tem só duas pontas.'),
  ('qui-t39',0,'Saturada: só simples entre carbonos. Insaturada: pelo menos uma dupla ou tripla entre carbonos.'),
  ('qui-t40',3,'Sem anel (aberta), duas pontas (normal), tem dupla C=C (insaturada) e só carbonos na cadeia (homogênea).'),
  ('qui-t41',3,'O heteroátomo (O, N, S…) faz parte da cadeia, intercalado entre carbonos.'),
  ('qui-t42',1,'O oxigênio está intercalado entre os carbonos: é um heteroátomo, e a cadeia é heterogênea.'),
  ('qui-t43',0,'Para ser heteroátomo, o átomo precisa estar entre dois carbonos. No etanol, o O está na ponta (no grupo OH).'),
  ('qui-t44',0,'O CH com o ramo é terciário (cadeia ramificada); só ligações simples (saturada); só carbonos (homogênea); sem anel (aberta).'),
  ('qui-t45',0,'O N está entre dois carbonos (heterogênea). Duas pontas (normal), só ligações simples (saturada), sem anel (aberta).'),
  ('qui-t46',0,'Tem dupla (insaturada), um CH com ramo (ramificada), só carbonos (homogênea) e nenhum anel (aberta).'),
  ('qui-t47',3,'Apesar do nome, "aromático" hoje quer dizer ter anel benzênico, e não ter cheiro.'),
  ('qui-t48',1,'Os elétrons das duplas se movimentam pelo anel (ressonância), o que deixa a molécula muito estável.'),
  ('qui-t49',0,'Polinuclear = mais de um anel benzênico; condensada = os anéis dividem átomos. Com um só anel, seria mononuclear.'),
  ('qui-t50',3,'Alicíclica = cíclica, mas não aromática.'),
  ('qui-p01',3,'CO, H₂CO₃ e cianetos têm carbono, mas são inorgânicos. A acetona é orgânica.'),
  ('qui-p02',0,'Ele obteve ureia aquecendo cianato de amônio, derrubando a teoria da força vital.'),
  ('qui-p03',2,'Tetravalência e encadeamento permitem cadeias de todos os tamanhos e formatos.'),
  ('qui-p04',2,'Grupos funcionais diferentes dão aromas diferentes: ésteres lembram frutas, tióis lembram ovo podre.'),
  ('qui-p05',2,'Primários: os CH₃ das pontas (2) e os três CH₃ dos parênteses (3) = 5. O C com dois ramos é quaternário (1). O CH com um ramo é terciário (1).'),
  ('qui-p06',1,'4 carbonos; hidrogênios: 2 + 1 + 0 + 1 = 4. Fórmula C₄H₄.'),
  ('qui-p07',0,'Esse carbono faz 1 ligação com o CH₂ e 3 com o N (≡), completando as 4.'),
  ('qui-p08',0,'6 carbonos em cadeia com ligações simples (hexano): 3 + 2 + 2 + 2 + 2 + 3 = 14 H.'),
  ('qui-p09',3,'O oxigênio está entre carbonos (heterogênea); duas pontas (normal); só simples (saturada); sem anel (aberta).'),
  ('qui-p10',3,'Há um ramo CH₃ (ramificada), uma dupla C=C (insaturada), só carbonos (homogênea) e nenhum anel (aberta).'),
  ('qui-p11',2,'Anel (fechada) sem benzeno (alicíclica), só simples (saturada) e só carbonos (homogênea).'),
  ('qui-p12',3,'Só o benzeno tem anel benzênico. Ciclo-hexano e ciclopropano são anéis alicíclicos; o hexano é aberto.');
